/*
Synthetic SQL Server Data Warehouse dataset for Data Engineering practice.

Tables:
    company_dim
    job_postings_fact
    skills_dim
    skills_job_dim

Designed to support:
    - INNER JOIN practice
    - GROUP BY / COUNT
    - remote job filtering
    - top skills for Data Engineers
    - star-schema / bridge-table practice

The data is synthetic and is NOT intended to represent real labor-market statistics.
*/

IF OBJECT_ID('dbo.skills_job_dim', 'U') IS NOT NULL DROP TABLE dbo.skills_job_dim;
IF OBJECT_ID('dbo.job_postings_fact', 'U') IS NOT NULL DROP TABLE dbo.job_postings_fact;
IF OBJECT_ID('dbo.skills_dim', 'U') IS NOT NULL DROP TABLE dbo.skills_dim;
IF OBJECT_ID('dbo.company_dim', 'U') IS NOT NULL DROP TABLE dbo.company_dim;
GO

CREATE TABLE dbo.company_dim (
    company_id INT NOT NULL PRIMARY KEY,
    name NVARCHAR(255) NOT NULL,
    link NVARCHAR(500) NULL,
    link_google NVARCHAR(1000) NULL,
    thumbnail NVARCHAR(1000) NULL
);
GO

CREATE TABLE dbo.skills_dim (
    skill_id INT NOT NULL PRIMARY KEY,
    skills NVARCHAR(100) NOT NULL,
    type NVARCHAR(100) NULL
);
GO

CREATE TABLE dbo.job_postings_fact (
    job_id INT NOT NULL PRIMARY KEY,
    company_id INT NOT NULL,
    job_title_short NVARCHAR(100) NULL,
    job_title NVARCHAR(500) NULL,
    job_location NVARCHAR(255) NULL,
    job_via NVARCHAR(255) NULL,
    job_schedule_type NVARCHAR(100) NULL,
    job_work_from_home BIT NOT NULL,
    search_location NVARCHAR(255) NULL,
    job_posted_date DATETIME2(0) NULL,
    job_no_degree_mention BIT NULL,
    job_health_insurance BIT NULL,
    job_country NVARCHAR(100) NULL,
    salary_rate NVARCHAR(50) NULL,
    salary_year_avg DECIMAL(12,2) NULL,
    salary_hour_avg DECIMAL(10,2) NULL,
    CONSTRAINT FK_job_company FOREIGN KEY (company_id)
        REFERENCES dbo.company_dim(company_id)
);
GO

CREATE TABLE dbo.skills_job_dim (
    job_id INT NOT NULL,
    skill_id INT NOT NULL,
    CONSTRAINT PK_skills_job_dim PRIMARY KEY (job_id, skill_id),
    CONSTRAINT FK_sjd_job FOREIGN KEY (job_id)
        REFERENCES dbo.job_postings_fact(job_id),
    CONSTRAINT FK_sjd_skill FOREIGN KEY (skill_id)
        REFERENCES dbo.skills_dim(skill_id)
);
GO


































































































































































































































































































































































































































































































































































-- Helpful indexes for JOIN/filter practice
CREATE INDEX IX_job_postings_company_id
    ON dbo.job_postings_fact(company_id);

CREATE INDEX IX_job_postings_role_remote
    ON dbo.job_postings_fact(job_title_short, job_work_from_home);

CREATE INDEX IX_skills_job_dim_skill_id
    ON dbo.skills_job_dim(skill_id);

CREATE INDEX IX_skills_job_dim_job_id
    ON dbo.skills_job_dim(job_id);
GO

-- Validation
SELECT 'company_dim' AS table_name, COUNT(*) AS row_count FROM dbo.company_dim
UNION ALL
SELECT 'skills_dim', COUNT(*) FROM dbo.skills_dim
UNION ALL
SELECT 'job_postings_fact', COUNT(*) FROM dbo.job_postings_fact
UNION ALL
SELECT 'skills_job_dim', COUNT(*) FROM dbo.skills_job_dim;
GO

-- Your first exercise (SQL Server syntax):
SELECT TOP (10)
    sd.skills,
    COUNT(*) AS demand_count
FROM dbo.job_postings_fact AS jp
INNER JOIN dbo.skills_job_dim AS sjd
    ON jp.job_id = sjd.job_id
INNER JOIN dbo.skills_dim AS sd
    ON sjd.skill_id = sd.skill_id
WHERE jp.job_title_short IN ('Data Engineer', 'Senior Data Engineer', 'Junior Data Engineer')
  AND jp.job_work_from_home = 1
GROUP BY sd.skills
ORDER BY demand_count DESC;
GO
